export const PACK_TIERS = ['terms', 'cards', 'search', 'explanations'];
export const PACK_TIER_FILES = {
    terms: 'terms.json',
    cards: 'cards.json',
    search: 'search-index.json',
    explanations: 'explanations.jsonl',
